parameters.jsCode:
// Decode the report and pull out the numbers. The panel writes a fixed
// headline line, so one regex is enough and there is nothing to keep in sync.
const item = $input.first().json;
if (!item || !item.content) return [];
const md = Buffer.from(item.content, 'base64').toString('utf8');

const head = md.match(/\*\*Overall: (\d+)% win, ([\d.]+) average R, ([+-]?[\d.]+)R expectancy\*\* \[([-\d.]+), ([-\d.]+)\] — (\w+)/);
const meta = md.match(/(\d+) trades across (\d+) simulated markets/);
const when = md.match(/# Paper trading cycle — (.+)$/m);
if (!head) return [];

const sha = item.sha;
const seen = $getWorkflowStaticData('global');
if (seen.lastSha === sha) return [];   // nothing new since last run
seen.lastSha = sha;

const negatives = [...md.matchAll(/\| ([^|]+) \| \d+ \| \d+% \| [\d.]+ \| ([+-][\d.]+)R \| \[([-\d.]+), ([-\d.]+)\] \| negative \|/g)]
  .map(m => `${m[1].trim()} ${m[2]}R`);

return [{ json: {
  cycle: (when ? when[1] : new Date().toISOString()).trim(),
  trades: meta ? +meta[1] : null,
  markets: meta ? +meta[2] : null,
  winRate: +head[1] / 100,
  avgR: +head[2],
  expectancy: +head[3],
  ciLow: +head[4],
  ciHigh: +head[5],
  verdict: head[6],
  negatives,
  markdown: md
}}];

