={{ JSON.stringify({
  parent: { database_id: $env.NOTION_CYCLES_DB },
  properties: {
    'Cycle': { title: [{ text: { content: $json.cycle } }] },
    'Run at': { date: { start: new Date().toISOString() } },
    'Trades': { number: $json.trades },
    'Win rate': { number: $json.winRate },
    'Avg R': { number: $json.avgR },
    'Expectancy R': { number: $json.expectancy },
    'Interval low': { number: $json.ciLow },
    'Interval high': { number: $json.ciHigh },
    'Verdict': { select: { name: $json.verdict } },
    'Change made': { rich_text: [{ text: { content: $json.negatives.length ? 'Negative slices found — panel applies one change next review' : 'None — no slice was significantly negative' } }] },
    'Weakest slice': { rich_text: [{ text: { content: $json.negatives.join('; ') || 'none' } }] },
    'Source': { select: { name: 'simulated' } }
  }
}) }}

={{ JSON.stringify({
  chat_id: $env.TG_CHAT,
  parse_mode: 'HTML',
  text: [
    '📊 <b>چرخهٔ ترید کاغذی</b>',
    `${$json.trades} معامله روی ${$json.markets} بازار`,
    `برد <b>${Math.round($json.winRate*100)}%</b> · میانگین <b>${$json.avgR}R</b>`,
    `انتظار <b>${$json.expectancy > 0 ? '+' : ''}${$json.expectancy}R</b> [${$json.ciLow} , ${$json.ciHigh}]`,
    $json.negatives.length ? `❌ برش منفی: ${$json.negatives.join(' · ')}` : '✅ هیچ برشی منفی معنادار نبود — تغییری لازم نیست'
  ].join('\n')
}) }}
